def run_e2e(write_report: Path | None = None) -> dict[str, Any]:
    fixture_doc = json_load(FIXTURES)
    temporary = tempfile.TemporaryDirectory(prefix="ckb-historical-batch-e2e-")
    root = Path(temporary.name)
    commands: list[dict[str, Any]] = []
    try:
        projects = []
        origins = {}
        retrieval = {}
        for fixture in fixture_doc["fixtures"]:
            repo, output, fixture_commands = historical_output(root, fixture)
            commands.extend(fixture_commands)
            old_result = retrieve_machine(output, "calculate", 800, 4, "fast")
            retrieval[fixture["fixture_id"]] = {
                "old_status": old_result["status"],
                "old_selected_count": len(old_result.get("selected_entities", [])),
            }
            projects.append(project_manifest(root, fixture, repo, output))
            origins[fixture["fixture_id"]] = _tree_manifest(output)
        manifest = root / "manifest.json"
        json_write(
            manifest,
            {
                "schema_version": 1,
                "batch_id": "historical-e2e",
                "allowed_roots": [str(root.resolve()), str(ROOT.resolve())],
                "projects": projects,
            },
        )
        plan_path = root / "plan.json"
        plan = create_knowledge_batch_plan(manifest, plan_path)
        if plan["status"] != "ready" or any(item["strategy"] != "compatible-migration" for item in plan["projects"]):
            raise RuntimeError(json.dumps(plan, ensure_ascii=False, indent=2))
        state_path = root / "state.json"
        applied = apply_knowledge_batch_plan(plan_path, state_path)
        if applied["status"] != "ready":
            staging_audits = {
                project["project_id"]: json_load(Path(project["staging"]) / "knowledge-batch/audit.json")
                for project in projects
                if (Path(project["staging"]) / "knowledge-batch/audit.json").is_file()
            }
            raise RuntimeError(json.dumps({"apply": applied, "staging_audits": staging_audits}, ensure_ascii=False, indent=2))
        for project in projects:
            new_result = retrieve_machine(Path(project["staging"]), "calculate", 800, 4, "fast")
            retrieval[project["project_id"]].update(
                {
                    "new_status": new_result["status"],
                    "new_selected_count": len(new_result.get("selected_entities", [])),
                }
            )
        if any(
            value["old_status"] != "passed"
            or value["new_status"] != "passed"
            or value["old_selected_count"] < 1
            or value["new_selected_count"] < 1
            for value in retrieval.values()
        ):
            raise RuntimeError(f"old/new center retrieval failed: {retrieval}")
        audited = audit_knowledge_batch_state(state_path)
        if audited["status"] != "passed":
            raise RuntimeError(json.dumps(audited, ensure_ascii=False, indent=2))
        cutover = cutover_knowledge_batch_state(state_path)
        if cutover["status"] != "passed":
            raise RuntimeError(json.dumps(cutover, ensure_ascii=False, indent=2))
        rollback = rollback_knowledge_batch_state(state_path)
        if rollback["status"] != "passed":
            raise RuntimeError(json.dumps(rollback, ensure_ascii=False, indent=2))
        restored = {
            project["project_id"]: _tree_manifest(Path(project["output"])) == origins[project["project_id"]]
            for project in projects
        }
        if not all(restored.values()):
            raise RuntimeError(f"historical rollback byte mismatch: {restored}")
        result = {
            "schema_version": 1,
            "status": "passed",
            "fixtures": [item["fixture_id"] for item in fixture_doc["fixtures"]],
            "historical_build_commands": commands,
            "plan": {"status": plan["status"], "strategies": {item["project_id"]: item["strategy"] for item in plan["projects"]}},
            "apply_status": applied["status"],
            "audit_status": audited["status"],
            "cutover_status": cutover["status"],
            "rollback_status": rollback["status"],
            "byte_exact_restored": restored,
            "old_and_new_retrieval": retrieval,
        }
        if write_report:
            json_write(write_report.resolve(), result)
        return result
    finally:
        try:
            temporary.cleanup()
        except OSError:
            shutil.rmtree(root, ignore_errors=True)

def option(args: list[str], name: str) -> str | None:
    if name not in args:
        return None
    index = args.index(name)
    return args[index + 1] if index + 1 < len(args) else None

def load(path: Path) -> dict[str, Any]:
    value = json.loads(path.read_text(encoding="utf-8-sig"))
    if not isinstance(value, dict):
        raise ValueError(f"JSON object required: {path}")
    return value

def percentile(values: list[float], probability: float) -> float:
    ordered = sorted(values)
    rank = (len(ordered) - 1) * probability
    lower = math.floor(rank)
    upper = math.ceil(rank)
    if lower == upper:
        return ordered[lower]
    return ordered[lower] + (ordered[upper] - ordered[lower]) * (rank - lower)

def quality(documents: list[dict[str, Any]], labels: list[dict[str, Any]]) -> tuple[float, float, float]:
    grades = {item["source_path"].replace("\\", "/").casefold(): int(item["grade"]) for item in labels}
    hits = [
        (int(item["rank"]), grades[item["source_path"].replace("\\", "/").casefold()])
        for item in documents[:8]
        if item["source_path"].replace("\\", "/").casefold() in grades
    ]
    recall = len({item["source_path"].replace("\\", "/").casefold() for item in documents[:8]} & set(grades)) / len(grades)
    reciprocal_rank = 1.0 / hits[0][0] if hits else 0.0
    dcg = sum((2**grade - 1) / math.log2(rank + 1) for rank, grade in hits)
    ideal = sorted(grades.values(), reverse=True)[:8]
    idcg = sum((2**grade - 1) / math.log2(index + 2) for index, grade in enumerate(ideal))
    return round(recall, 9), round(reciprocal_rank, 9), round(dcg / idcg if idcg else 0.0, 9)
